const hasValue=value=>Boolean(text(value))&&!unknownBriefValues.has(text(value).toLocaleLowerCase('ru'));
function sentenceForMatch(value,index,length){
 const starts=['\n','.','!','?'].map(mark=>value.lastIndexOf(mark,Math.max(0,index-1))).filter(position=>position>=0),start=starts.length?Math.max(...starts)+1:0;
 const ends=['\n','.','!','?'].map(mark=>value.indexOf(mark,index+length)).filter(position=>position>=0),end=ends.length?Math.min(...ends):value.length;
 return excerpt(value.slice(start,end).trim(),150);
}
function inferParticipationPreference(value){
 const source=text(value);if(!source)return null;
 const cues=[
  {key:'calm',pattern:/(спокойн|камерн|свободн.{0,14}общен|наблюдат|без плотн.{0,12}программ)/i},
  {key:'voluntary',pattern:/(без.{0,18}(?:конкурс|соревн|обязательн.{0,8}участи|активн.{0,8}программ)|не\s+(?:хотим|нужн|подходит).{0,18}(?:конкурс|соревн|активн)|не.{0,12}заставл|по желани|добровол|можно пропуст|выбирать.{0,12}сам|сам.{0,12}выбират)/i},
  {key:'active',pattern:/(активн.{0,14}(?:программ|участи|формат)|интерактив|командн.{0,14}(?:задан|игр)|соревнован|спортивн.{0,14}(?:часть|формат)|игров.{0,14}задан)/i}
 ];
 for(const cue of cues){const match=cue.pattern.exec(source);if(match)return {key:cue.key,evidence:sentenceForMatch(source,match.index,match[0].length)};}
 return null;
}
const asksBudgetHelp=value=>/^(?:нужна помощь с оценкой бюджета|помогите оценить бюджет|нужно оценить бюджет)$/i.test(text(value));
const excerpt=(value,max=240)=>{
 const valueText=text(value);if(valueText.length<=max)return valueText;
 const cut=valueText.slice(0,max-1),space=cut.lastIndexOf(' ');
 return (space>max*.65?cut.slice(0,space):cut)+'…';
};
const quote=(value,max=150)=>'«'+excerpt(value,max)+'»';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=value=>{try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password?url.href:'';}catch{return '';}};
const safeAssetImage=value=>{const path=String(value??'').trim();return /^\/custom\/[A-Za-z0-9._/-]+\.(?:avif|gif|jpe?g|png|webp)$/i.test(path)&&!path.split('/').includes('..')?path:'';};
function eventIdeaSourceImagesMarkup(sources=[]){
 const seen=new Set(),images=[];
 for(const source of Array.isArray(sources)?sources:[]){const src=safeAssetImage(source?.image);if(!src||seen.has(src))continue;seen.add(src);images.push({src,alt:'Проект «'+(source.workTitle||source.title||'Работа агентства')+'» агентства «'+(source.agencyName||'из каталога')+'»',caption:(source.agencyName?source.agencyName+' · ':'')+(source.workTitle||source.title||'Работа агентства')});}
 if(!images.length)return '';
 return `<div class="event-idea-source-images" aria-label="Фотографии исходных работ">${images.map(image=>`<figure><img src="${esc(image.src)}" alt="${esc(image.alt)}" loading="lazy" decoding="async"><figcaption>${esc(image.caption)}</figcaption></figure>`).join('')}</div>`;
}
function customerAnswersMarkup(sources=[]){
 const seen=new Set(),answers=[];
 for(const source of Array.isArray(sources)?sources:[])for(const item of source.customerAnswers||[]){
  const key=JSON.stringify([source.agencySlug,source.workSlug,item.question,item.answer]);
  if(seen.has(key))continue;seen.add(key);
  if(answers.length<3)answers.push({agency:source.agencyName,work:source.workTitle,question:item.question,answer:item.answer});
 }
 if(!answers.length)return '';
 return `<section class="event-idea-resonance event-idea-client-answers"><strong>Ответ клиента к работе из исходной заявки</strong>${answers.map(item=>`<div><p>${esc(item.agency)} · ${esc(item.work)}</p><p><b>Вопрос из карточки:</b> ${esc(item.question)}</p><p><b>Ответ клиента (дословно):</b><br>${esc(item.answer).replace(/\n/g,'<br>')}</p></div>`).join('')}<p class="small muted">Это слова клиента о примере, а не согласие на предложенный сценарий. Если ответ ограничивает или отвергает приём, учтите это перед обсуждением варианта.</p></section>`;
}
function timelineFor(journey,duration){
 const total=Number(duration);if(!Number.isInteger(total)||!Object.hasOwn(eventDurations,String(total)))return [];
 const path=text(journey).replace(/\.\s+(?:Число гостей|Предварительный ориентир).*$/i,'');
 let steps=path.split(/\s*→\s*/).map(step=>step.trim().replace(/[.;]+$/,'')).filter(Boolean);
 if(steps.length>5)steps=[...steps.slice(0,4),steps.slice(4).join(' → ')];
 if(!steps.length)return [];
 const clock=minutes=>String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0');
 const nominal=Math.round((total/steps.length)/5)*5;let start=0;
 return steps.map((step,index)=>{const end=index===steps.length-1?total:Math.min(total-(steps.length-index-1)*5,start+Math.max(5,nominal));const slot=clock(start)+'–'+clock(end)+' · '+step;start=end;return slot;});
}

